window.__DAILY_CHUNKS__[3] = [{"week":19,"level":"A2","theme":"简单将来时与计划表达","days":[{"day":1,"theme":"词汇 · 工作与职业","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：工作与职业","body":"本周词汇主战场是工作与职业（Le travail et les métiers）。先到 vocab.html#t11 把词表扫一遍，把 <span class=\"fr\" data-fr=\"un projet\">un projet</span>（计划）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）、<span class=\"fr\" data-fr=\"l'avenir\">l'avenir</span>（未来）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t11","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5021","level":"A2","skill":"vocab","prompt":"« un objectif » 的意思是？","options":["目标","物品","反对"],"answer":"目标","explain":"objectif 是目标；objet 是物品；opposition 是反对。","source":"词汇 · 抽象概念"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"vocab","title":"搭配与辨析：dans deux ans / améliorer","body":"把 <span class=\"fr\" data-fr=\"dans deux ans\">dans deux ans</span>（两年后）和 <span class=\"fr\" data-fr=\"améliorer\">améliorer</span>（改善）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t11","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5022","level":"A2","skill":"vocab","prompt":"« améliorer » 的意思是？","options":["改善","评价","记住"],"answer":"改善","explain":"améliorer 是改善、提高；évaluer 是评价；mémoriser 是记住。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"listen","title":"听音辨词：工作与职业","body":"打开 对话页的 d18 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>（文凭）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d18","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je partirai en France l'année prochaine.\">Je partirai en France l'année prochaine.</span>（我明年去法国。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：工作与职业 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un projet\">un projet</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"l'avenir\">l'avenir</span> <span class=\"fr\" data-fr=\"dans deux ans\">dans deux ans</span> <span class=\"fr\" data-fr=\"améliorer\">améliorer</span> <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>。说不出来的词立刻回到 vocab.html#t11 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t11","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]}]},{"day":2,"theme":"语法 · 简单将来时","type":"grammar","steps":[{"type":"grammar","title":"语法点：简单将来时","body":"【简单将来时】简单将来时的构成是「不定式加词尾 -ai, -as, -a, -ons, -ez, -ont」，以 -re 结尾的动词要先去掉 e（je prendrai）。常见不规则词干有 être 变 ser-、avoir 变 aur-、aller 变 ir-、faire 变 fer-、venir 变 viendr-。日常口语更常用 aller 加不定式，简单将来时多用于书面语与承诺。 例句：<span class=\"fr\" data-fr=\"Je partirai en France l'année prochaine.\">Je partirai en France l'année prochaine.</span>（我明年去法国。）；<span class=\"fr\" data-fr=\"Nous serons prêts à huit heures.\">Nous serons prêts à huit heures.</span>（我们八点准备好。）。对照 grammar-a1a2.html#futur-simple 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#futur-simple","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5021","level":"A2","skill":"grammar","prompt":"Demain, nous ___ à Lyon.（être）","options":["serons","sommes","serions"],"answer":"serons","explain":"être 的简单将来时词干是 ser-，nous 对应 serons。","source":"语法 · 简单将来时"},{"ref":"bank:grammar:A2:将来时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 简单将来时 的规则和两个例句，再打开 grammar-a1a2.html#futur-simple 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#futur-simple","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5022","level":"A2","skill":"grammar","prompt":"« aller » 的简单将来时词干是？","options":["ir-","all-","vais-"],"answer":"ir-","explain":"aller 的将来时词干是不规则的 ir-，写作 j'irai。","source":"语法 · 简单将来时"},{"ref":"bank:grammar:A2:将来时"}]},{"type":"read","title":"在短文里找简单将来时","body":"在 grammar-a1a2.html#futur-simple 的例句和章末小测里挑 5 句，圈出所有属于「简单将来时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#futur-simple","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je partirai en France l'année prochaine.\">Je partirai en France l'année prochaine.</span>（我明年去法国。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，简单将来时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：三种「将来」的语体差别","body":"今天再回 grammar-a1a2.html#avenir-styles 看一遍 三种「将来」的语体差别，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#avenir-styles","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:将来时"}]}]},{"day":3,"theme":"精听 · 对话页的 d18 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d18 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d18","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5011","level":"A2","skill":"listening","prompt":"听到 /il fəʁa/ 时对应哪个形式？","options":["il fera","il fait","il ferait"],"answer":"il fera","explain":"faire 的将来时词干是 fer-，第三人称单数写作 il fera。","source":"语法 · 简单将来时"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听访谈谈「五年后的打算」，摘录 8 句将来时。","src":"dialogue.html#d18","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un projet\">un projet</span>（计划）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）、<span class=\"fr\" data-fr=\"l'avenir\">l'avenir</span>（未来）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t11","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「简单将来时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d18","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 简单将来时与计划表达","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：说三年计划（学习、工作、旅行）5 分钟，全部用将来时与条件式表达愿望。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5006","level":"A2","skill":"speaking","prompt":"说三年计划时，「我将会」应说？","options":["je serai","je suis","j'étais"],"answer":"je serai","explain":"谈论将来用简单将来时；je serai 是 être 的将来时形式。","source":"语法 · 简单将来时"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d18 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、简单将来时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d18","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"dans deux ans\">dans deux ans</span>（两年后）、<span class=\"fr\" data-fr=\"améliorer\">améliorer</span>（改善）、<span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>（文凭）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t11 再看一遍例句。","src":"vocab.html#t11","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 简单将来时与计划表达","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页将来时章节与时间状语（dans, d'ici, à partir de）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5011","level":"A2","skill":"reading","prompt":"« dans deux ans » 的意思是？","options":["两年后","两年来","两年间"],"answer":"两年后","explain":"dans 加时间段表示从现在起多久之后；depuis 才是「以来」。","source":"词汇 · 时间"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「简单将来时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un projet\">un projet</span>（计划）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t11","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#futur-simple，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#futur-simple","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:将来时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「简单将来时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 简单将来时与计划表达","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 150 词「我的一年法语计划」，用上 8 个不规则将来时。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5006","level":"A2","skill":"writing","prompt":"「我明年去法国」正确写法是？","options":["Je partirai en France l'année prochaine.","Je pars en France l'année prochaine.","Je partirai à France l'année prochaine."],"answer":"Je partirai en France l'année prochaine.","explain":"阴性国家名前用 en，将来时用 partirai。","source":"语法 · 简单将来时"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#futur-simple，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#futur-simple","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:将来时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「简单将来时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un projet\">un projet</span>（计划）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 简单将来时与计划表达","type":"review","steps":[{"type":"review","title":"本周回顾：简单将来时与计划表达","body":"这一周围绕「简单将来时与计划表达」展开：语法主线是 简单将来时，词汇主线是 工作与职业。先用 3 句话口头复述本周学了什么，再打开日历页第 19 周清单逐条核对里程碑。","src":"calendar.html#wk-19","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"语法复盘：简单将来时","body":"从 grammar-a1a2.html#futur-simple 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#futur-simple","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:将来时"}]},{"type":"review","title":"词汇自测：工作与职业","body":"遮住中文看 vocab.html#t11 的 6 个核心词：<span class=\"fr\" data-fr=\"un projet\">un projet</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"l'avenir\">l'avenir</span> <span class=\"fr\" data-fr=\"dans deux ans\">dans deux ans</span> <span class=\"fr\" data-fr=\"améliorer\">améliorer</span> <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t11","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5023","level":"A2","skill":"vocab","prompt":"「未来」用法语说是？","options":["l'avenir","le passé","le présent"],"answer":"l'avenir","explain":"l'avenir 是未来；le passé 是过去；le présent 是现在。","source":"词汇 · 时间"},{"id":"q-vocab-a2-5024","level":"A2","skill":"vocab","prompt":"« un diplôme » 的意思是？","options":["文凭","课程","考试"],"answer":"文凭","explain":"diplôme 是文凭、学位；cours 是课程；examen 是考试。","source":"词汇 · 教育"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d18","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5012","level":"A2","skill":"listening","prompt":"听到 /vu səʁe pʁɛ/ 时表示？","options":["你们会准备好的","你们已经准备好了","你们本来会准备好"],"answer":"你们会准备好的","explain":"serez 是 être 的简单将来时 vous 形式。","source":"语法 · 简单将来时"},{"id":"q-read-a2-5012","level":"A2","skill":"reading","prompt":"「五年前」的表达是？","options":["il y a cinq ans","dans cinq ans","depuis cinq ans"],"answer":"il y a cinq ans","explain":"il y a 加时间段表示「……以前」；dans 表将来某时；depuis 表以来。","source":"词汇 · 时间"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 简单将来时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#futur-simple 再核对一次。","src":"grammar-a1a2.html#avenir-styles","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5023","level":"A2","skill":"grammar","prompt":"« Ils ___ le projet la semaine prochaine. »（finir）","options":["finiront","finissent","finissaient"],"answer":"finiront","explain":"finir 的将来时是规则变化：不定式加 -ont，ils finiront。","source":"语法 · 简单将来时"},{"id":"q-gram-a2-5024","level":"A2","skill":"grammar","prompt":"下列哪个不是将来时的不规则词干？","options":["voul-","aur-","ser-"],"answer":"voul-","explain":"vouloir 的将来时词干是 voudr-（je voudrai），voul- 是现在时词干。","source":"语法 · 简单将来时"},{"ref":"bank:grammar:A2:将来时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":20,"level":"A2","theme":"简单条件式：礼貌、愿望与假设入门","days":[{"day":1,"theme":"词汇 · 身体与健康","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：身体与健康","body":"身体与健康（Le corps et la santé）是这一周要反复见面的主题域。打开 vocab.html#t3，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un médecin\">un médecin</span>（医生）、<span class=\"fr\" data-fr=\"une ordonnance\">une ordonnance</span>（处方）、<span class=\"fr\" data-fr=\"un symptôme\">un symptôme</span>（症状）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t3","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5025","level":"A2","skill":"vocab","prompt":"« un symptôme » 的意思是？","options":["症状","处方","治疗"],"answer":"症状","explain":"symptôme 是症状；ordonnance 是处方；traitement 是治疗。","source":"词汇 · 健康"},{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"vocab","title":"搭配与辨析：avoir mal à / un traitement","body":"<span class=\"fr\" data-fr=\"avoir mal à\">avoir mal à</span>（……疼）与 <span class=\"fr\" data-fr=\"un traitement\">un traitement</span>（治疗）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t3","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5026","level":"A2","skill":"vocab","prompt":"« avoir mal à » 后面接什么？","options":["身体部位","时间","地点"],"answer":"身体部位","explain":"avoir mal à la tête、avoir mal au dos 表示某个部位疼，à 后接缩合冠词加身体部位。","source":"词汇 · 健康表达"},{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"listen","title":"听音辨词：身体与健康","body":"打开 对话页的 d14 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"se reposer\">se reposer</span>（休息）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d14","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je voudrais un rendez-vous avec le médecin.\">Je voudrais un rendez-vous avec le médecin.</span>（我想约一次医生。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：身体与健康 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un médecin\">un médecin</span> <span class=\"fr\" data-fr=\"une ordonnance\">une ordonnance</span> <span class=\"fr\" data-fr=\"un symptôme\">un symptôme</span> <span class=\"fr\" data-fr=\"avoir mal à\">avoir mal à</span> <span class=\"fr\" data-fr=\"un traitement\">un traitement</span> <span class=\"fr\" data-fr=\"se reposer\">se reposer</span>。说不出来的词立刻回到 vocab.html#t3 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t3","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:身体与健康"}]}]},{"day":2,"theme":"语法 · 简单条件式","type":"grammar","steps":[{"type":"grammar","title":"语法点：简单条件式","body":"【简单条件式】简单条件式的构成是「简单将来时词干加未完成过去时词尾 -ais, -ais, -ait, -ions, -iez, -aient」，如 je voudrais、il pourrait。它有三个常见用法：礼貌请求、表达愿望、报道未经证实的信息。si 加未完成过去时、主句用条件式，构成第一型假设。 例句：<span class=\"fr\" data-fr=\"Je voudrais un rendez-vous avec le médecin.\">Je voudrais un rendez-vous avec le médecin.</span>（我想约一次医生。）；<span class=\"fr\" data-fr=\"Si j'avais le temps, je ferais du sport.\">Si j'avais le temps, je ferais du sport.</span>（如果我有时间，就会去运动。）。对照 grammar-a1a2.html#conditionnel-present 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#conditionnel-present","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5025","level":"A2","skill":"grammar","prompt":"礼貌地约诊，应说？","options":["Je voudrais un rendez-vous.","Je veux un rendez-vous.","Je voudrai un rendez-vous."],"answer":"Je voudrais un rendez-vous.","explain":"条件式 Je voudrais 表示礼貌请求；voudrai 是简单将来时，语气生硬。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:A2:条件式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#conditionnel-present 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Je voudrais un rendez-vous avec le médecin.\">Je voudrais un rendez-vous avec le médecin.</span>（我想约一次医生。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#conditionnel-present","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5026","level":"A2","skill":"grammar","prompt":"« Si j'avais le temps, je ___ du sport. »","options":["ferais","fais","ferai"],"answer":"ferais","explain":"si 加未完成过去时，主句用条件式现在时 ferais。","source":"语法 · 第一型假设"},{"ref":"bank:grammar:A2:条件式"}]},{"type":"read","title":"在短文里找简单条件式","body":"在 grammar-a1a2.html#conditionnel-present 的例句和章末小测里挑 5 句，圈出所有属于「简单条件式」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#conditionnel-present","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je voudrais un rendez-vous avec le médecin.\">Je voudrais un rendez-vous avec le médecin.</span>（我想约一次医生。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，简单条件式 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：条件式现在时：三大用法","body":"今天再回 grammar-b1b2.html#cond-usage 看一遍 条件式现在时：三大用法，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#cond-usage","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:条件式"}]}]},{"day":3,"theme":"精听 · 对话页的 d14 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d14 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d14","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5013","level":"A2","skill":"listening","prompt":"听到 /il puʁɛ/ 时最可能是？","options":["il pourrait","il pourra","il peut"],"answer":"il pourrait","explain":"pourrait 是条件式，用于委婉或假设；pourra 是简单将来时。","source":"语法 · 条件式"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听客服或医生对话，标记所有礼貌条件式。","src":"dialogue.html#d14","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un médecin\">un médecin</span>（医生）、<span class=\"fr\" data-fr=\"une ordonnance\">une ordonnance</span>（处方）、<span class=\"fr\" data-fr=\"un symptôme\">un symptôme</span>（症状）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t3","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「简单条件式 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d14","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 礼貌、愿望与假设入门","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：模拟看病：描述症状、医生建议、请假请求，共 4 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5007","level":"A2","skill":"speaking","prompt":"看病时描述「我头疼」应说？","options":["J'ai mal à la tête.","Je suis mal à la tête.","J'ai douleur à la tête."],"answer":"J'ai mal à la tête.","explain":"法语用 avoir mal à 加身体部位表示疼痛，不能用 être mal。","source":"词汇 · 健康表达"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d14 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、简单条件式 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d14","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"avoir mal à\">avoir mal à</span>（……疼）、<span class=\"fr\" data-fr=\"un traitement\">un traitement</span>（治疗）、<span class=\"fr\" data-fr=\"se reposer\">se reposer</span>（休息）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t3 再看一遍例句。","src":"vocab.html#t3","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 礼貌、愿望与假设入门","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页条件式章节与对话页 A2 看病篇，标出所有条件式。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5013","level":"A2","skill":"reading","prompt":"« Il serait déjà parti. » 中 serait 表示？","options":["未经证实的消息","确定的将来","命令"],"answer":"未经证实的消息","explain":"条件式可以用来报道尚未核实的信息，语气上有所保留。","source":"语法 · 条件式用法"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un médecin\">un médecin</span>（医生）、<span class=\"fr\" data-fr=\"une ordonnance\">une ordonnance</span>（处方）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t3","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#conditionnel-present，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#conditionnel-present","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:条件式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「简单条件式」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 礼貌、愿望与假设入门","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写一封 100 词礼貌请假邮件，用上 3 个条件式。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5007","level":"A2","skill":"writing","prompt":"请假邮件里「我希望……」最得体的说法是？","options":["Je souhaiterais…","Je veux…","Donne-moi…"],"answer":"Je souhaiterais…","explain":"条件式 souhaiterais 在正式邮件里比 veux 礼貌得多。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#conditionnel-present，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#conditionnel-present","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:条件式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「简单条件式」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un médecin\">un médecin</span>（医生）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 礼貌、愿望与假设入门","type":"review","steps":[{"type":"review","title":"本周回顾：简单条件式：礼貌、愿望与假设入门","body":"这一周围绕「简单条件式：礼貌、愿望与假设入门」展开：语法主线是 简单条件式，词汇主线是 身体与健康。先用 3 句话口头复述本周学了什么，再打开日历页第 20 周清单逐条核对里程碑。","src":"calendar.html#wk-20","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"review","title":"语法复盘：简单条件式","body":"从 grammar-a1a2.html#conditionnel-present 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#conditionnel-present","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:条件式"}]},{"type":"review","title":"词汇自测：身体与健康","body":"遮住中文看 vocab.html#t3 的 6 个核心词：<span class=\"fr\" data-fr=\"un médecin\">un médecin</span> <span class=\"fr\" data-fr=\"une ordonnance\">une ordonnance</span> <span class=\"fr\" data-fr=\"un symptôme\">un symptôme</span> <span class=\"fr\" data-fr=\"avoir mal à\">avoir mal à</span> <span class=\"fr\" data-fr=\"un traitement\">un traitement</span> <span class=\"fr\" data-fr=\"se reposer\">se reposer</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t3","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5027","level":"A2","skill":"vocab","prompt":"「处方」用法语说是？","options":["une ordonnance","un symptôme","un traitement"],"answer":"une ordonnance","explain":"ordonnance 是处方；symptôme 是症状；traitement 是疗程。","source":"词汇 · 健康"},{"id":"q-vocab-a2-5028","level":"A2","skill":"vocab","prompt":"« se reposer » 的意思是？","options":["休息","运动","吃药"],"answer":"休息","explain":"se reposer 是休息；faire du sport 是运动；prendre un médicament 是吃药。","source":"词汇 · 健康"},{"ref":"bank:vocab:A1:身体与健康"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d14","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5014","level":"A2","skill":"listening","prompt":"医生问 « Où avez-vous mal ? » 是在问？","options":["哪里疼","什么时候疼","疼了多久"],"answer":"哪里疼","explain":"où 问部位，这句话是问疼痛的位置。","source":"词汇 · 就医"},{"id":"q-read-a2-5014","level":"A2","skill":"reading","prompt":"第一型假设的结构是？","options":["si 加未完成过去时，主句条件式现在时","si 加现在时，主句将来时","si 加愈过去时，主句条件式过去时"],"answer":"si 加未完成过去时，主句条件式现在时","explain":"si 加现在时是现实条件，si 加愈过去时是反事实，未完成过去时配条件式现在时才是第一型假设。","source":"语法 · 假设三型"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 简单条件式 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#conditionnel-present 再核对一次。","src":"grammar-b1b2.html#cond-usage","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5027","level":"A2","skill":"grammar","prompt":"« Pourriez-vous m'aider ? » 中 pourriez 是？","options":["条件式，表示礼貌","简单将来时","命令式"],"answer":"条件式，表示礼貌","explain":"pourriez 是 pouvoir 的条件式，用于礼貌请求。","source":"语法 · 条件式礼貌用法"},{"id":"q-gram-a2-5028","level":"A2","skill":"grammar","prompt":"« Il ___ prendre ce médicament trois fois par jour. »（devoir，建议）","options":["devrait","doit","devra"],"answer":"devrait","explain":"条件式 devrait 表示委婉建议；doit 语气较强，devra 表将来。","source":"语法 · 条件式用法"},{"ref":"bank:grammar:A2:条件式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":21,"level":"A2","theme":"间接宾语代词与副代词 y / en","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"本周词汇主战场是高频动词与万能表达（Les verbes fréquents et les expressions utiles）。先到 vocab.html#t25 把词表扫一遍，把 <span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span>（给……打电话）、<span class=\"fr\" data-fr=\"répondre à\">répondre à</span>（回答）、<span class=\"fr\" data-fr=\"un message\">un message</span>（留言）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5029","level":"A2","skill":"vocab","prompt":"« un message » 的意思是？","options":["留言","信使","消息灵通"],"answer":"留言","explain":"un message 是留言、消息；un messager 是信使。","source":"词汇 · 通讯"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：un service / la poste","body":"把 <span class=\"fr\" data-fr=\"un service\">un service</span>（服务）和 <span class=\"fr\" data-fr=\"la poste\">la poste</span>（邮局）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5030","level":"A2","skill":"vocab","prompt":"« un compte » 的意思是？","options":["账户","数量","故事"],"answer":"账户","explain":"compte 是账户；conte 是故事，两词读音相同，要按上下文分辨。","source":"词汇 · 银行"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d16、d05 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un compte\">un compte</span>（账户）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d16","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je lui ai téléphoné hier soir.\">Je lui ai téléphoné hier soir.</span>（我昨晚给他打了电话。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span> <span class=\"fr\" data-fr=\"répondre à\">répondre à</span> <span class=\"fr\" data-fr=\"un message\">un message</span> <span class=\"fr\" data-fr=\"un service\">un service</span> <span class=\"fr\" data-fr=\"la poste\">la poste</span> <span class=\"fr\" data-fr=\"un compte\">un compte</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · 间接宾语代词 lui / leur","type":"grammar","steps":[{"type":"grammar","title":"语法点：间接宾语代词 lui / leur","body":"【间接宾语代词 lui / leur】间接宾语代词 lui / leur 代替「à 加人」，放在动词前；直接宾语用 le / la / les。副代词 y 代替「à 加事物」或地点，en 代替「de 加事物」或数量，位置同样在动词前。y 与 en 都不能用来指人。 例句：<span class=\"fr\" data-fr=\"Je lui ai téléphoné hier soir.\">Je lui ai téléphoné hier soir.</span>（我昨晚给他打了电话。）；<span class=\"fr\" data-fr=\"J'y vais tous les jours et j'en reviens à six heures.\">J'y vais tous les jours et j'en reviens à six heures.</span>（我每天都去那里，六点回来。）。对照 grammar-a1a2.html#pro-coi 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#pro-coi","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5029","level":"A2","skill":"grammar","prompt":"« Je téléphone à Marie. » 用代词改写是？","options":["Je lui téléphone.","Je la téléphone.","Je le téléphone."],"answer":"Je lui téléphone.","explain":"téléphoner à 加人用间接宾语代词 lui；la 是直接宾语代词。","source":"语法 · 间接宾语代词"},{"ref":"bank:grammar:A2:代词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 间接宾语代词 lui / leur 的规则和两个例句，再打开 grammar-a1a2.html#pro-coi 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#pro-coi","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5030","level":"A2","skill":"grammar","prompt":"« Je vais à la poste. » 用 y 改写是？","options":["J'y vais.","Je la vais.","Je lui vais."],"answer":"J'y vais.","explain":"y 代替 à 加地点或事物，位置在动词前。","source":"语法 · 副代词 y"},{"ref":"bank:grammar:A2:代词"}]},{"type":"read","title":"在短文里找间接宾语代词 lui / leur","body":"在 grammar-a1a2.html#pro-coi 的例句和章末小测里挑 5 句，圈出所有属于「间接宾语代词 lui / leur」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#pro-coi","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je lui ai téléphoné hier soir.\">Je lui ai téléphoné hier soir.</span>（我昨晚给他打了电话。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，间接宾语代词 lui / leur 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：副代词 y 与 en","body":"今天再回 grammar-a1a2.html#pro-y-en 看一遍 副代词 y 与 en，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#pro-y-en","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:代词"}]}]},{"day":3,"theme":"精听 · 对话页的 d16、d05 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d16、d05 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d16","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5015","level":"A2","skill":"listening","prompt":"听到 /ʒə lɥi ɛ di/ 时最可能是？","options":["Je lui ai dit.","Je le lui ai dit.","Je l'ai dit."],"answer":"Je lui ai dit.","explain":"lui 表示向他说，是间接宾语；复合过去时里代词放在助动词前。","source":"语法 · 间接宾语代词"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听电话留言，写出每一处被代词替换的原始表达。","src":"dialogue.html#d16","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span>（给……打电话）、<span class=\"fr\" data-fr=\"répondre à\">répondre à</span>（回答）、<span class=\"fr\" data-fr=\"un message\">un message</span>（留言）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「间接宾语代词 lui / leur 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d16","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 间接宾语代词与副代词 y / en","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：把 15 句完整句口头替换成代词句，要求脱口而出。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5008","level":"A2","skill":"speaking","prompt":"把「我在银行有账户」改写成带 y 的句子？","options":["J'y ai un compte.","Je lui ai un compte.","J'en ai un compte."],"answer":"J'y ai un compte.","explain":"à la banque 用 y 代替；en 代替 de 加事物或数量。","source":"语法 · 副代词 y"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d16、d05 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、间接宾语代词 lui / leur 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d16","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un service\">un service</span>（服务）、<span class=\"fr\" data-fr=\"la poste\">la poste</span>（邮局）、<span class=\"fr\" data-fr=\"un compte\">un compte</span>（账户）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 间接宾语代词与副代词 y / en","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页代词章节，重点看「代词放动词前」的语序规则。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5015","level":"A2","skill":"reading","prompt":"« Il en veut deux. » 中 en 代替的是？","options":["数量结构中的名词","地点","人"],"answer":"数量结构中的名词","explain":"en 代替数量结构里的名词，数量词 deux 保留在句末。","source":"语法 · 副代词 en"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「间接宾语代词 lui / leur」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span>（给……打电话）、<span class=\"fr\" data-fr=\"répondre à\">répondre à</span>（回答）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#pro-coi，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#pro-coi","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:代词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「间接宾语代词 lui / leur」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 间接宾语代词与副代词 y / en","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：做一张改写表：左列原句、右列代词替换句，各 15 例。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5008","level":"A2","skill":"writing","prompt":"「我已经回答了他」正确写法是？","options":["Je lui ai déjà répondu.","Je l'ai déjà répondu.","J'ai déjà lui répondu."],"answer":"Je lui ai déjà répondu.","explain":"répondre à 加人用 lui，且代词必须放在助动词 ai 之前。","source":"语法 · 间接宾语代词"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#pro-coi，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#pro-coi","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:代词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「间接宾语代词 lui / leur」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span>（给……打电话）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 间接宾语代词与副代词 y / en","type":"review","steps":[{"type":"review","title":"本周回顾：间接宾语代词与副代词 y / en","body":"这一周围绕「间接宾语代词与副代词 y / en」展开：语法主线是 间接宾语代词 lui / leur，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 21 周清单逐条核对里程碑。","src":"calendar.html#wk-21","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：间接宾语代词 lui / leur","body":"从 grammar-a1a2.html#pro-coi 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#pro-coi","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:代词"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"téléphoner à\">téléphoner à</span> <span class=\"fr\" data-fr=\"répondre à\">répondre à</span> <span class=\"fr\" data-fr=\"un message\">un message</span> <span class=\"fr\" data-fr=\"un service\">un service</span> <span class=\"fr\" data-fr=\"la poste\">la poste</span> <span class=\"fr\" data-fr=\"un compte\">un compte</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5031","level":"A2","skill":"vocab","prompt":"« répondre à » 的意思是？","options":["回答","重复","回忆"],"answer":"回答","explain":"répondre à 是回答、回复；répéter 是重复；se rappeler 是回忆。","source":"词汇 · 通讯"},{"id":"q-vocab-a2-5032","level":"A2","skill":"vocab","prompt":"「邮局」用法语说是？","options":["la poste","la banque","la mairie"],"answer":"la poste","explain":"la poste 是邮局；la banque 是银行；la mairie 是市政厅。","source":"词汇 · 办事场景"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d16","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5016","level":"A2","skill":"listening","prompt":"听到 /ʒɑ̃ vø/ 时表示？","options":["我想要一些","我在那里想要","我给他"],"answer":"我想要一些","explain":"en 代替 de 加名词，veux 后保留数量含义；y 才指地点。","source":"语法 · 副代词 en"},{"id":"q-read-a2-5016","level":"A2","skill":"reading","prompt":"« y » 与 « en » 都不能代替？","options":["人","事物","地点"],"answer":"人","explain":"y 与 en 代替事物或地点；指人要用 lui / leur 或重读代词形式。","source":"语法 · 副代词"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 间接宾语代词 lui / leur 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#pro-coi 再核对一次。","src":"grammar-a1a2.html#pro-y-en","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5031","level":"A2","skill":"grammar","prompt":"« Tu as parlé à tes parents ? — Oui, je ___ ai parlé. »","options":["leur","lui","les"],"answer":"leur","explain":"parents 是复数，间接宾语代词用 leur；les 是直接宾语代词。","source":"语法 · 间接宾语代词"},{"id":"q-gram-a2-5032","level":"A2","skill":"grammar","prompt":"« Cette idée ? J'y pense souvent. » 中 y 代替的是？","options":["à cette idée","de cette idée","cette idée 作直接宾语"],"answer":"à cette idée","explain":"penser à 加事物用 y 代替；penser de 才可能用 en。","source":"语法 · 副代词 y"},{"ref":"bank:grammar:A2:代词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":22,"level":"A2","theme":"代词顺序、命令式与代词连用","days":[{"day":1,"theme":"词汇 · 购物与消费","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：购物与消费","body":"购物与消费（Les achats et la consommation）是这一周要反复见面的主题域。打开 vocab.html#t7，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span>（退款）、<span class=\"fr\" data-fr=\"un reçu\">un reçu</span>（收据）、<span class=\"fr\" data-fr=\"changer\">changer</span>（更换）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t7","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5033","level":"A2","skill":"vocab","prompt":"« un remboursement » 的意思是？","options":["退款","收据","折扣"],"answer":"退款","explain":"remboursement 是退款；reçu 是收据；remise 是折扣。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"vocab","title":"搭配与辨析：un produit / une réclamation","body":"<span class=\"fr\" data-fr=\"un produit\">un produit</span>（产品）与 <span class=\"fr\" data-fr=\"une réclamation\">une réclamation</span>（投诉）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t7","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5034","level":"A2","skill":"vocab","prompt":"« rendre » 的意思是？","options":["归还","收到","购买"],"answer":"归还","explain":"rendre 是归还；recevoir 是收到；acheter 是购买。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"listen","title":"听音辨词：购物与消费","body":"打开 对话页的 d15 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"rendre\">rendre</span>（归还）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d15","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il me le donne.\">Il me le donne.</span>（他把它给我。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：购物与消费 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span> <span class=\"fr\" data-fr=\"un reçu\">un reçu</span> <span class=\"fr\" data-fr=\"changer\">changer</span> <span class=\"fr\" data-fr=\"un produit\">un produit</span> <span class=\"fr\" data-fr=\"une réclamation\">une réclamation</span> <span class=\"fr\" data-fr=\"rendre\">rendre</span>。说不出来的词立刻回到 vocab.html#t7 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t7","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]}]},{"day":2,"theme":"语法 · 代词顺序表","type":"grammar","steps":[{"type":"grammar","title":"语法点：代词顺序表","body":"【代词顺序表】双代词连用时顺序固定：me / te / se / nous / vous，接着 le / la / les，接着 lui / leur，接着 y，最后 en。肯定命令式里代词后置并用连字符连接，me 变成 moi：Donne-le-moi ! 否定命令式则回到正常语序：Ne me le donne pas。 例句：<span class=\"fr\" data-fr=\"Il me le donne.\">Il me le donne.</span>（他把它给我。）；<span class=\"fr\" data-fr=\"Donne-le-moi !\">Donne-le-moi !</span>（把它给我！）。对照 grammar-a1a2.html#pro-ordre 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#pro-ordre","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5033","level":"A2","skill":"grammar","prompt":"« Il me donne le livre. » 用双代词改写是？","options":["Il me le donne.","Il le me donne.","Il me lui donne."],"answer":"Il me le donne.","explain":"顺序是 me 在前、le 在后，写作 me le。","source":"语法 · 代词顺序"},{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#pro-ordre 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Il me le donne.\">Il me le donne.</span>（他把它给我。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#pro-ordre","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5034","level":"A2","skill":"grammar","prompt":"肯定命令式「把它给我！」应说？","options":["Donne-le-moi !","Donne-moi-le !","Donne le moi !"],"answer":"Donne-le-moi !","explain":"肯定命令式代词后置，直接宾语在前，me 变重读形 moi 并用连字符连接。","source":"语法 · 命令式与代词"},{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"read","title":"在短文里找代词顺序表","body":"在 grammar-a1a2.html#pro-ordre 的例句和章末小测里挑 5 句，圈出所有属于「代词顺序表」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#pro-ordre","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il me le donne.\">Il me le donne.</span>（他把它给我。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，代词顺序表 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：命令式","body":"今天再回 grammar-a1a2.html#imperatif 看一遍 命令式，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#imperatif","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:代词顺序"}]}]},{"day":3,"theme":"精听 · 对话页的 d15 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d15 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d15","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5017","level":"A2","skill":"listening","prompt":"听到 /dɔn lə mwa/ 时对应写法？","options":["Donne-le-moi !","Donne-moi-le !","Ne me le donne pas !"],"answer":"Donne-le-moi !","explain":"听到的顺序是动词、le、moi，符合肯定命令式的代词顺序。","source":"语法 · 命令式与代词"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听退货或投诉对话，写出含双代词的句子。","src":"dialogue.html#d15","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span>（退款）、<span class=\"fr\" data-fr=\"un reçu\">un reçu</span>（收据）、<span class=\"fr\" data-fr=\"changer\">changer</span>（更换）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t7","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「代词顺序表 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d15","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 代词顺序、命令式与代词连用","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：角色扮演退货：陈述问题、要求退款、礼貌表达不满。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5009","level":"A2","skill":"speaking","prompt":"要求退款时最得体的说法是？","options":["Je voudrais un remboursement, s'il vous plaît.","Remboursez-moi tout de suite !","Je veux mon argent."],"answer":"Je voudrais un remboursement, s'il vous plaît.","explain":"投诉也要保持礼貌：条件式加 s'il vous plaît 比命令式有效得多。","source":"语法 · 礼貌表达"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d15 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、代词顺序表 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d15","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un produit\">un produit</span>（产品）、<span class=\"fr\" data-fr=\"une réclamation\">une réclamation</span>（投诉）、<span class=\"fr\" data-fr=\"rendre\">rendre</span>（归还）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t7 再看一遍例句。","src":"vocab.html#t7","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 代词顺序、命令式与代词连用","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页命令式与代词顺序章节，把顺序表默写下来。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5017","level":"A2","skill":"reading","prompt":"« Ne me le donne pas. » 中代词的位置是？","options":["在动词前","在动词后","分列动词两侧"],"answer":"在动词前","explain":"否定命令式代词回到动词前，顺序仍是 me 在前、le 在后。","source":"语法 · 命令式与代词"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span>（退款）、<span class=\"fr\" data-fr=\"un reçu\">un reçu</span>（收据）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t7","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#pro-ordre，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#pro-ordre","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「代词顺序表」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 代词顺序、命令式与代词连用","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写一份 120 词投诉信（网购商品有问题）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5009","level":"A2","skill":"writing","prompt":"投诉信里陈述问题最合适的一句是？","options":["Le produit que j'ai reçu est endommagé.","Le produit est pas bon.","Je déteste ce produit."],"answer":"Le produit que j'ai reçu est endommagé.","explain":"书面投诉要客观描述事实，用关系从句说明收到的商品有问题。","source":"写作 · 投诉信"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#pro-ordre，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#pro-ordre","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「代词顺序表」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span>（退款）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 代词顺序、命令式与代词连用","type":"review","steps":[{"type":"review","title":"本周回顾：代词顺序、命令式与代词连用","body":"这一周围绕「代词顺序、命令式与代词连用」展开：语法主线是 代词顺序表，词汇主线是 购物与消费。先用 3 句话口头复述本周学了什么，再打开日历页第 22 周清单逐条核对里程碑。","src":"calendar.html#wk-22","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"review","title":"语法复盘：代词顺序表","body":"从 grammar-a1a2.html#pro-ordre 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#pro-ordre","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"review","title":"词汇自测：购物与消费","body":"遮住中文看 vocab.html#t7 的 6 个核心词：<span class=\"fr\" data-fr=\"un remboursement\">un remboursement</span> <span class=\"fr\" data-fr=\"un reçu\">un reçu</span> <span class=\"fr\" data-fr=\"changer\">changer</span> <span class=\"fr\" data-fr=\"un produit\">un produit</span> <span class=\"fr\" data-fr=\"une réclamation\">une réclamation</span> <span class=\"fr\" data-fr=\"rendre\">rendre</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t7","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5035","level":"A2","skill":"vocab","prompt":"« un produit » 的意思是？","options":["产品","生产者","价格"],"answer":"产品","explain":"produit 是产品；producteur 是生产者；prix 是价格。","source":"词汇 · 购物"},{"id":"q-vocab-a2-5036","level":"A2","skill":"vocab","prompt":"« une réclamation » 的意思是？","options":["投诉","退款","发票"],"answer":"投诉","explain":"réclamation 是投诉；remboursement 是退款；facture 是发票。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d15","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5018","level":"A2","skill":"listening","prompt":"听到 /il lɥi a dɔne/ 时表示？","options":["他把它给了他","他只是给了他","他给自己了"],"answer":"他把它给了他","explain":"le 是直接宾语、lui 是间接宾语，顺序为 le lui。","source":"语法 · 代词顺序"},{"id":"q-read-a2-5018","level":"A2","skill":"reading","prompt":"« Je t'en parle. » 中代词顺序是？","options":["te 在前、en 在后","en 在前、te 在后","两者可以互换"],"answer":"te 在前、en 在后","explain":"顺序固定为 me/te/se/nous/vous，然后 le/la/les、lui/leur、y，最后 en。","source":"语法 · 代词顺序"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 代词顺序表 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#pro-ordre 再核对一次。","src":"grammar-a1a2.html#imperatif","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5035","level":"A2","skill":"grammar","prompt":"「这些照片，给我看看！」应说？","options":["Montre-les-moi !","Montre-moi-les !","Montre-les-me !"],"answer":"Montre-les-moi !","explain":"肯定命令式里直接宾语 les 在前、moi 在后，用连字符连接。","source":"语法 · 命令式与代词"},{"id":"q-gram-a2-5036","level":"A2","skill":"grammar","prompt":"« ___ en parles-tu ? »（对谁谈起此事）","options":["Lui","Le","La"],"answer":"Lui","explain":"parler de quelque chose à quelqu'un 用间接宾语代词 lui，且 lui 不能指事物。","source":"语法 · 间接宾语代词"},{"ref":"bank:grammar:B1:代词顺序"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":23,"level":"A2","theme":"工作与求职：词汇、简历与动机信","days":[{"day":1,"theme":"词汇 · 工作与职业","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：工作与职业","body":"本周词汇主战场是工作与职业（Le travail et les métiers）。先到 vocab.html#t11 把词表扫一遍，把 <span class=\"fr\" data-fr=\"un entretien\">un entretien</span>（面试）、<span class=\"fr\" data-fr=\"un CV\">un CV</span>（简历）、<span class=\"fr\" data-fr=\"une expérience\">une expérience</span>（经验）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t11","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5037","level":"A2","skill":"vocab","prompt":"« un entretien » 的意思是？","options":["面试","企业","合同"],"answer":"面试","explain":"entretien 是面试或谈话；entreprise 是企业；contrat 是合同。","source":"词汇 · 求职"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"vocab","title":"搭配与辨析：une compétence / un poste","body":"把 <span class=\"fr\" data-fr=\"une compétence\">une compétence</span>（能力）和 <span class=\"fr\" data-fr=\"un poste\">un poste</span>（职位）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t11","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5038","level":"A2","skill":"vocab","prompt":"« une compétence » 的意思是？","options":["能力","竞争","同事"],"answer":"能力","explain":"compétence 是能力、技能；concurrence 是竞争；collègue 是同事。","source":"词汇 · 求职"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"listen","title":"听音辨词：工作与职业","body":"打开 对话页的 d20 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"une entreprise\">une entreprise</span>（企业）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d20","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"J'ai travaillé deux ans dans une banque.\">J'ai travaillé deux ans dans une banque.</span>（我在一家银行工作过两年。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：工作与职业 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un entretien\">un entretien</span> <span class=\"fr\" data-fr=\"un CV\">un CV</span> <span class=\"fr\" data-fr=\"une expérience\">une expérience</span> <span class=\"fr\" data-fr=\"une compétence\">une compétence</span> <span class=\"fr\" data-fr=\"un poste\">un poste</span> <span class=\"fr\" data-fr=\"une entreprise\">une entreprise</span>。说不出来的词立刻回到 vocab.html#t11 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t11","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]}]},{"day":2,"theme":"语法 · 复合过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：复合过去时","body":"【复合过去时】简历与动机信里的经验表达常用复合过去时（J'ai travaillé deux ans chez…），能力用 être capable de、savoir faire、avoir de l'expérience en。礼貌地表达愿望用条件式：Je souhaiterais rejoindre votre équipe。这一周没有新语法点，重点是把已学时态用进真实文书。 例句：<span class=\"fr\" data-fr=\"J'ai travaillé deux ans dans une banque.\">J'ai travaillé deux ans dans une banque.</span>（我在一家银行工作过两年。）；<span class=\"fr\" data-fr=\"Je souhaiterais rejoindre votre équipe.\">Je souhaiterais rejoindre votre équipe.</span>（我希望能加入贵团队。）。对照 grammar-a1a2.html#passe-compose 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#passe-compose","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5037","level":"A2","skill":"grammar","prompt":"描述过去的工作经验，应用？","options":["复合过去时","现在时","简单将来时"],"answer":"复合过去时","explain":"已完成的工作经历用复合过去时：J'ai travaillé deux ans chez…。","source":"语法 · 复合过去时"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 复合过去时 的规则和两个例句，再打开 grammar-a1a2.html#passe-compose 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#passe-compose","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5038","level":"A2","skill":"grammar","prompt":"动机信里表达愿望最得体的说法是？","options":["Je souhaiterais rejoindre votre équipe.","Je veux travailler chez vous.","Donnez-moi ce poste."],"answer":"Je souhaiterais rejoindre votre équipe.","explain":"条件式 souhaiterais 是正式书面表达的首选。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"read","title":"在短文里找复合过去时","body":"在 grammar-a1a2.html#passe-compose 的例句和章末小测里挑 5 句，圈出所有属于「复合过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#passe-compose","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"J'ai travaillé deux ans dans une banque.\">J'ai travaillé deux ans dans une banque.</span>（我在一家银行工作过两年。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，复合过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：简单条件式","body":"今天再回 grammar-a1a2.html#conditionnel-present 看一遍 简单条件式，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#conditionnel-present","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d20 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d20 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d20","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5019","level":"A2","skill":"listening","prompt":"招聘广告里 « CDD » 指的是？","options":["定期合同","无固定期限合同","实习"],"answer":"定期合同","explain":"CDD 是 contrat à durée déterminée（定期合同）；CDI 才是无固定期限合同。","source":"词汇 · 职场"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段招聘广告与一次简短面试，记录关键信息。","src":"dialogue.html#d20","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un entretien\">un entretien</span>（面试）、<span class=\"fr\" data-fr=\"un CV\">un CV</span>（简历）、<span class=\"fr\" data-fr=\"une expérience\">une expérience</span>（经验）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t11","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「复合过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d20","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 词汇、简历与动机信","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：模拟面试前 5 分钟：自我介绍、为什么想来、有什么经验。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5010","level":"A2","skill":"speaking","prompt":"面试中回答「为什么想来」时，最得体的开头是？","options":["Je m'intéresse à votre entreprise parce que…","Je veux de l'argent.","Parce que je cherche un travail."],"answer":"Je m'intéresse à votre entreprise parce que…","explain":"面试回答要给出具体理由，从对企业的兴趣与自身匹配度切入。","source":"口语 · 面试"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d20 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、复合过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d20","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une compétence\">une compétence</span>（能力）、<span class=\"fr\" data-fr=\"un poste\">un poste</span>（职位）、<span class=\"fr\" data-fr=\"une entreprise\">une entreprise</span>（企业）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t11 再看一遍例句。","src":"vocab.html#t11","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 词汇、简历与动机信","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 2 篇法语招聘广告，画出职位要求。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5019","level":"A2","skill":"reading","prompt":"招聘广告中 « Bac+3 » 表示？","options":["高中毕业后三年高等教育","三年工作经验","三次面试"],"answer":"高中毕业后三年高等教育","explain":"Bac+3 指高中毕业后再读三年，相当于本科水平。","source":"词汇 · 教育"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「复合过去时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un entretien\">un entretien</span>（面试）、<span class=\"fr\" data-fr=\"un CV\">un CV</span>（简历）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t11","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#passe-compose，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#passe-compose","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「复合过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 词汇、简历与动机信","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写法语简历一页和 100 词动机信初稿，两项都要留档以便第 36 周改写。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5010","level":"A2","skill":"writing","prompt":"动机信中表达经验最合适的一句是？","options":["J'ai acquis une expérience solide en gestion.","Je connais un peu.","J'ai fait des choses."],"answer":"J'ai acquis une expérience solide en gestion.","explain":"正式文书要用具体、可验证的表达，避免模糊说法。","source":"写作 · 动机信"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#passe-compose，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#passe-compose","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「复合过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un entretien\">un entretien</span>（面试）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 词汇、简历与动机信","type":"review","steps":[{"type":"review","title":"本周回顾：工作与求职：词汇、简历与动机信","body":"这一周围绕「工作与求职：词汇、简历与动机信」展开：语法主线是 复合过去时，词汇主线是 工作与职业。先用 3 句话口头复述本周学了什么，再打开日历页第 23 周清单逐条核对里程碑。","src":"calendar.html#wk-23","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"语法复盘：复合过去时","body":"从 grammar-a1a2.html#passe-compose 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#passe-compose","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"review","title":"词汇自测：工作与职业","body":"遮住中文看 vocab.html#t11 的 6 个核心词：<span class=\"fr\" data-fr=\"un entretien\">un entretien</span> <span class=\"fr\" data-fr=\"un CV\">un CV</span> <span class=\"fr\" data-fr=\"une expérience\">une expérience</span> <span class=\"fr\" data-fr=\"une compétence\">une compétence</span> <span class=\"fr\" data-fr=\"un poste\">un poste</span> <span class=\"fr\" data-fr=\"une entreprise\">une entreprise</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t11","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5039","level":"A2","skill":"vocab","prompt":"« un poste » 的意思是？","options":["职位","邮局","岗位空缺"],"answer":"职位","explain":"poste 指职位或岗位，也可指邮局，需要按上下文区分。","source":"词汇 · 职场"},{"id":"q-vocab-a2-5040","level":"A2","skill":"vocab","prompt":"« une entreprise » 的意思是？","options":["企业","创业者","面试"],"answer":"企业","explain":"entreprise 是企业；entrepreneur 是创业者；entretien 是面试。","source":"词汇 · 职场"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d20","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5020","level":"A2","skill":"listening","prompt":"面试官问 « Quelles sont vos qualités ? » 是在问？","options":["你的优点","你的缺点","你的期望薪资"],"answer":"你的优点","explain":"qualités 是优点、长处；défauts 才是缺点。","source":"口语 · 面试"},{"id":"q-read-a2-5020","level":"A2","skill":"reading","prompt":"简历中 « expérience professionnelle » 一栏应写？","options":["工作经历","兴趣爱好","教育背景"],"answer":"工作经历","explain":"这一栏专写工作经历；教育背景对应 formation。","source":"词汇 · 简历"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 复合过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#passe-compose 再核对一次。","src":"grammar-a1a2.html#conditionnel-present","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5039","level":"A2","skill":"grammar","prompt":"「我在一家公司实习过」正确写法是？","options":["J'ai fait un stage dans une entreprise.","Je fais un stage dans une entreprise l'an dernier.","J'ai faire un stage."],"answer":"J'ai fait un stage dans une entreprise.","explain":"过去的经历用复合过去时，且助动词后面不能接不定式原形。","source":"语法 · 复合过去时"},{"id":"q-gram-a2-5040","level":"A2","skill":"grammar","prompt":"「我有三年经验」应说？","options":["J'ai trois ans d'expérience.","Je suis trois ans d'expérience.","J'ai trois ans expérience."],"answer":"J'ai trois ans d'expérience.","explain":"表达经验用 avoir 加时间段再加 de 加名词。","source":"语法 · 经验表达"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":24,"level":"A2","theme":"比较级、最高级与数量表达","days":[{"day":1,"theme":"词汇 · 购物与消费","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：购物与消费","body":"购物与消费（Les achats et la consommation）是这一周要反复见面的主题域。打开 vocab.html#t7，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"cher\">cher</span>（贵的）、<span class=\"fr\" data-fr=\"moins cher\">moins cher</span>（更便宜）、<span class=\"fr\" data-fr=\"la qualité\">la qualité</span>（质量）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t7","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5041","level":"A2","skill":"vocab","prompt":"« une réduction » 的意思是？","options":["折扣","退款","涨价"],"answer":"折扣","explain":"réduction 是折扣、减价；remboursement 是退款；augmentation 是涨价。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"vocab","title":"搭配与辨析：un prix / une réduction","body":"<span class=\"fr\" data-fr=\"un prix\">un prix</span>（价格）与 <span class=\"fr\" data-fr=\"une réduction\">une réduction</span>（折扣）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t7","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5042","level":"A2","skill":"vocab","prompt":"« la qualité » 的意思是？","options":["质量","数量","价格"],"answer":"质量","explain":"qualité 是质量；quantité 是数量；prix 是价格。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"listen","title":"听音辨词：购物与消费","body":"打开 对话页的 d04 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"meilleur\">meilleur</span>（更好的（形容词））这样的词如果没听出来，单独标出来。","src":"dialogue.html#d04","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Ce téléphone est plus cher que l'autre.\">Ce téléphone est plus cher que l'autre.</span>（这部手机比另一部贵。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：购物与消费 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"cher\">cher</span> <span class=\"fr\" data-fr=\"moins cher\">moins cher</span> <span class=\"fr\" data-fr=\"la qualité\">la qualité</span> <span class=\"fr\" data-fr=\"un prix\">un prix</span> <span class=\"fr\" data-fr=\"une réduction\">une réduction</span> <span class=\"fr\" data-fr=\"meilleur\">meilleur</span>。说不出来的词立刻回到 vocab.html#t7 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t7","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]}]},{"day":2,"theme":"语法 · 比较级与最高级","type":"grammar","steps":[{"type":"grammar","title":"语法点：比较级与最高级","body":"【比较级与最高级】比较级用 plus / moins / aussi 加形容词或副词加 que；bon 的比较级是 meilleur，bien 的比较级是 mieux，不能写成 plus bon。最高级用 le / la / les plus（moins），副词最高级固定用 le plus。数量副词 très / trop / assez / beaucoup 与 de 的搭配要一并复习。 例句：<span class=\"fr\" data-fr=\"Ce téléphone est plus cher que l'autre.\">Ce téléphone est plus cher que l'autre.</span>（这部手机比另一部贵。）；<span class=\"fr\" data-fr=\"C'est la meilleure solution.\">C'est la meilleure solution.</span>（这是最好的方案。）。对照 grammar-a1a2.html#comparaison 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#comparaison","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5041","level":"A2","skill":"grammar","prompt":"« Ce livre est ___ intéressant que l'autre. »","options":["aussi","autant","tant"],"answer":"aussi","explain":"同级比较用 aussi 加形容词加 que；autant 修饰动词。","source":"语法 · 比较级"},{"ref":"bank:grammar:A2:比较级"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#comparaison 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Ce téléphone est plus cher que l'autre.\">Ce téléphone est plus cher que l'autre.</span>（这部手机比另一部贵。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#comparaison","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5042","level":"A2","skill":"grammar","prompt":"bon 的比较级是？","options":["meilleur","plus bon","mieux"],"answer":"meilleur","explain":"bon 的比较级是不规则的 meilleur；mieux 是副词 bien 的比较级。","source":"语法 · 比较级特殊形式"},{"ref":"bank:grammar:A2:比较级"}]},{"type":"read","title":"在短文里找比较级与最高级","body":"在 grammar-a1a2.html#comparaison 的例句和章末小测里挑 5 句，圈出所有属于「比较级与最高级」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#comparaison","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Ce téléphone est plus cher que l'autre.\">Ce téléphone est plus cher que l'autre.</span>（这部手机比另一部贵。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，比较级与最高级 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：形容词、副词的比较级","body":"今天再回 grammar-a1a2.html#comp-adj 看一遍 形容词、副词的比较级，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#comp-adj","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:比较级"}]}]},{"day":3,"theme":"精听 · 对话页的 d04 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d04 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d04","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5021","level":"A2","skill":"listening","prompt":"听到 /ply ʃɛʁ/ 时表示？","options":["更贵","更便宜","一样贵"],"answer":"更贵","explain":"plus cher 是比较级「更贵」；moins cher 才是更便宜。","source":"语法 · 比较级"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听产品对比类音频，记录听到的比较结构。","src":"dialogue.html#d04","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"cher\">cher</span>（贵的）、<span class=\"fr\" data-fr=\"moins cher\">moins cher</span>（更便宜）、<span class=\"fr\" data-fr=\"la qualité\">la qualité</span>（质量）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t7","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「比较级与最高级 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d04","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 比较级、最高级与数量表达","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：对比两个城市、两种手机、两份工作，各 4 句。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5011","level":"A2","skill":"speaking","prompt":"对比两种手机时最自然的结构是？","options":["A est plus léger que B.","A est plus léger de B.","A est léger plus que B."],"answer":"A est plus léger que B.","explain":"比较级是 plus 加形容词加 que，que 不能换成 de。","source":"语法 · 比较级"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d04 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、比较级与最高级 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d04","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un prix\">un prix</span>（价格）、<span class=\"fr\" data-fr=\"une réduction\">une réduction</span>（折扣）、<span class=\"fr\" data-fr=\"meilleur\">meilleur</span>（更好的（形容词））轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t7 再看一遍例句。","src":"vocab.html#t7","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 比较级、最高级与数量表达","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页比较级章节与特殊形式表。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5021","level":"A2","skill":"reading","prompt":"« le moins cher » 的意思是？","options":["最便宜的","不太贵的","比较便宜的"],"answer":"最便宜的","explain":"le moins 加形容词构成最低级，表示最不……。","source":"语法 · 最高级"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"cher\">cher</span>（贵的）、<span class=\"fr\" data-fr=\"moins cher\">moins cher</span>（更便宜）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t7","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#comparaison，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#comparaison","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:比较级"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「比较级与最高级」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 比较级、最高级与数量表达","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 150 词对比短文（两种方案选一个并说明理由）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5011","level":"A2","skill":"writing","prompt":"对比短文里表达「我更喜欢第一个方案」应说？","options":["Je préfère la première solution.","Je préfère plus la première solution.","Je préfère mieux la première solution."],"answer":"Je préfère la première solution.","explain":"préférer 本身已含比较意味，不能再加 plus 或 mieux。","source":"语法 · 比较级"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#comparaison，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#comparaison","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:比较级"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「比较级与最高级」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"cher\">cher</span>（贵的）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 比较级、最高级与数量表达","type":"review","steps":[{"type":"review","title":"本周回顾：比较级、最高级与数量表达","body":"这一周围绕「比较级、最高级与数量表达」展开：语法主线是 比较级与最高级，词汇主线是 购物与消费。先用 3 句话口头复述本周学了什么，再打开日历页第 24 周清单逐条核对里程碑。","src":"calendar.html#wk-24","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"review","title":"语法复盘：比较级与最高级","body":"从 grammar-a1a2.html#comparaison 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#comparaison","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:比较级"}]},{"type":"review","title":"词汇自测：购物与消费","body":"遮住中文看 vocab.html#t7 的 6 个核心词：<span class=\"fr\" data-fr=\"cher\">cher</span> <span class=\"fr\" data-fr=\"moins cher\">moins cher</span> <span class=\"fr\" data-fr=\"la qualité\">la qualité</span> <span class=\"fr\" data-fr=\"un prix\">un prix</span> <span class=\"fr\" data-fr=\"une réduction\">une réduction</span> <span class=\"fr\" data-fr=\"meilleur\">meilleur</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t7","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5043","level":"A2","skill":"vocab","prompt":"« moins cher » 的意思是？","options":["更便宜","更贵","免费"],"answer":"更便宜","explain":"moins cher 是更便宜；plus cher 是更贵；gratuit 是免费。","source":"词汇 · 购物"},{"id":"q-vocab-a2-5044","level":"A2","skill":"vocab","prompt":"« un prix » 的意思是？","options":["价格","奖励","质量"],"answer":"价格","explain":"prix 是价格，也可指奖项；qualité 是质量。","source":"词汇 · 购物"},{"ref":"bank:vocab:A1:购物与消费"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d04","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5022","level":"A2","skill":"listening","prompt":"「两部手机一样贵」应说？","options":["Les deux téléphones coûtent aussi cher.","Les deux téléphones coûtent plus cher.","Les deux téléphones coûtent le plus cher."],"answer":"Les deux téléphones coûtent aussi cher.","explain":"同级比较用 aussi cher 表示一样贵；plus 与 le plus 分别是比较级和最高级。","source":"语法 · 比较级"},{"id":"q-read-a2-5022","level":"A2","skill":"reading","prompt":"« bien » 的比较级是？","options":["mieux","meilleur","plus bien"],"answer":"mieux","explain":"bien 是副词，比较级是 mieux；meilleur 用于形容词 bon。","source":"语法 · 比较级特殊形式"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 比较级与最高级 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#comparaison 再核对一次。","src":"grammar-a1a2.html#comp-adj","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5043","level":"A2","skill":"grammar","prompt":"« C'est ___ solution. »（最好的）","options":["la meilleure","la plus bonne","la mieux"],"answer":"la meilleure","explain":"最高级要基于比较级形式：bon 变 meilleur，再加 la 构成 la meilleure。","source":"语法 · 最高级"},{"id":"q-gram-a2-5044","level":"A2","skill":"grammar","prompt":"« Il travaille ___ que moi. »（更努力）","options":["plus dur","plus durement","mieux dur"],"answer":"plus dur","explain":"副词比较级用 plus 加副词加 que，这里用 dur 作副词表示努力地。","source":"语法 · 比较级"},{"ref":"bank:grammar:A2:比较级"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":25,"level":"A2","theme":"阅读与听力冲刺：400 词短文 + 泛听泛读","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"une société\">une société</span>（社会）、<span class=\"fr\" data-fr=\"un article\">un article</span>（文章）、<span class=\"fr\" data-fr=\"un résumé\">un résumé</span>（摘要）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5045","level":"A2","skill":"vocab","prompt":"« un résumé » 的意思是？","options":["摘要","题目","评论"],"answer":"摘要","explain":"résumé 是摘要；titre 是题目；commentaire 是评论。","source":"词汇 · 阅读"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：une opinion / un média","body":"把 <span class=\"fr\" data-fr=\"une opinion\">une opinion</span>（观点）和 <span class=\"fr\" data-fr=\"un média\">un média</span>（媒体）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5046","level":"A2","skill":"vocab","prompt":"« une opinion » 的意思是？","options":["观点","选项","反对"],"answer":"观点","explain":"opinion 是观点；option 是选项；opposition 是反对。","source":"词汇 · 观点"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d20 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un titre\">un titre</span>（标题）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d20","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Le livre que j'ai lu parle de la société.\">Le livre que j'ai lu parle de la société.</span>（我读的那本书讲的是社会。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une société\">une société</span> <span class=\"fr\" data-fr=\"un article\">un article</span> <span class=\"fr\" data-fr=\"un résumé\">un résumé</span> <span class=\"fr\" data-fr=\"une opinion\">une opinion</span> <span class=\"fr\" data-fr=\"un média\">un média</span> <span class=\"fr\" data-fr=\"un titre\">un titre</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · 关系代词 qui / que / où","type":"grammar","steps":[{"type":"grammar","title":"语法点：关系代词 qui / que / où","body":"【关系代词 qui / que / où】这一周不学新语法，专攻「语法识别速度」：读到句子立刻指出时态与代词。关系代词 qui 作从句主语、que 作直接宾语、où 作时间或地点状语，是拆解长句的三把钥匙；时间介词 depuis / pendant / il y a / dans 各管一种时间关系。 例句：<span class=\"fr\" data-fr=\"Le livre que j'ai lu parle de la société.\">Le livre que j'ai lu parle de la société.</span>（我读的那本书讲的是社会。）；<span class=\"fr\" data-fr=\"J'habite ici depuis trois ans.\">J'habite ici depuis trois ans.</span>（我在这里住了三年。）。对照 grammar-a1a2.html#relatifs-a1a2 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5045","level":"A2","skill":"grammar","prompt":"« Le film ___ j'ai vu est intéressant. »","options":["que","qui","où"],"answer":"que","explain":"从句里 j'ai vu 缺直接宾语，用关系代词 que。","source":"语法 · 关系代词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 关系代词 qui / que / où 的规则和两个例句，再打开 grammar-a1a2.html#relatifs-a1a2 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5046","level":"A2","skill":"grammar","prompt":"« J'habite ici ___ trois ans. »","options":["depuis","pendant","il y a"],"answer":"depuis","explain":"depuis 加时间段表示从过去延续到现在；pendant 指一段已结束的时间。","source":"语法 · 时间介词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"read","title":"在短文里找关系代词 qui / que / où","body":"在 grammar-a1a2.html#relatifs-a1a2 的例句和章末小测里挑 5 句，圈出所有属于「关系代词 qui / que / où」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Le livre que j'ai lu parle de la société.\">Le livre que j'ai lu parle de la société.</span>（我读的那本书讲的是社会。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，关系代词 qui / que / où 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：时间介词","body":"今天再回 grammar-a1a2.html#prep-temps 看一遍 时间介词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#prep-temps","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:关系代词"}]}]},{"day":3,"theme":"精听 · 对话页的 d20 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d20 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d20","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5023","level":"A2","skill":"listening","prompt":"泛听时最应该抓的是？","options":["主旨与关键词","每个生词的拼写","语法术语"],"answer":"主旨与关键词","explain":"泛听训练的是抓主旨与关键词的能力，逐词抠会打断理解。","source":"考试 · 听力策略"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：每天 30 分钟泛听（新闻简讯、播客），只抓主旨，不查词。","src":"dialogue.html#d20","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une société\">une société</span>（社会）、<span class=\"fr\" data-fr=\"un article\">un article</span>（文章）、<span class=\"fr\" data-fr=\"un résumé\">un résumé</span>（摘要）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「关系代词 qui / que / où 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d20","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 400 词短文 + 泛听泛读","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用一段短文做「复述加我的看法」：1 分钟复述加 1 分钟观点。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5012","level":"A2","skill":"speaking","prompt":"复述短文时，第一步应该？","options":["用自己的话概括主旨","逐句背诵原文","先评价再概括"],"answer":"用自己的话概括主旨","explain":"复述先概括主旨，再补细节；评价放在第二部分。","source":"口语 · 复述"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d20 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、关系代词 qui / que / où 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d20","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une opinion\">une opinion</span>（观点）、<span class=\"fr\" data-fr=\"un média\">un média</span>（媒体）、<span class=\"fr\" data-fr=\"un titre\">un titre</span>（标题）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 400 词短文 + 泛听泛读","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：精读考试页 4 篇 B2 长文中的 2 篇，限时 15 分钟一篇。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5023","level":"A2","skill":"reading","prompt":"限时 15 分钟读一篇长文，第一遍应？","options":["先读标题与首段抓主旨","逐词翻译","先做细节题"],"answer":"先读标题与首段抓主旨","explain":"先建立主旨框架，再带着问题回文定位细节。","source":"考试 · 阅读策略"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「关系代词 qui / que / où」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une société\">une société</span>（社会）、<span class=\"fr\" data-fr=\"un article\">un article</span>（文章）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#relatifs-a1a2，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「关系代词 qui / que / où」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 400 词短文 + 泛听泛读","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 150 词读后感（概括、评价、与个人经历的联系）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5012","level":"A2","skill":"writing","prompt":"读后感里的「概括」部分应该？","options":["改写原文要点，不照抄","逐句引用原文","只写个人感受"],"answer":"改写原文要点，不照抄","explain":"摘要必须改写，照抄原文不算概括能力。","source":"写作 · 摘要"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#relatifs-a1a2，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「关系代词 qui / que / où」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une société\">une société</span>（社会）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 400 词短文 + 泛听泛读","type":"review","steps":[{"type":"review","title":"本周回顾：阅读与听力冲刺：400 词短文 + 泛听泛读","body":"这一周围绕「阅读与听力冲刺：400 词短文 + 泛听泛读」展开：语法主线是 关系代词 qui / que / où，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 25 周清单逐条核对里程碑。","src":"calendar.html#wk-25","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：关系代词 qui / que / où","body":"从 grammar-a1a2.html#relatifs-a1a2 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"une société\">une société</span> <span class=\"fr\" data-fr=\"un article\">un article</span> <span class=\"fr\" data-fr=\"un résumé\">un résumé</span> <span class=\"fr\" data-fr=\"une opinion\">une opinion</span> <span class=\"fr\" data-fr=\"un média\">un média</span> <span class=\"fr\" data-fr=\"un titre\">un titre</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5047","level":"A2","skill":"vocab","prompt":"« un média » 的意思是？","options":["媒体","中间","研究者"],"answer":"媒体","explain":"média 指媒体；milieu 是中间；chercheur 是研究者。","source":"词汇 · 媒体"},{"id":"q-vocab-a2-5048","level":"A2","skill":"vocab","prompt":"« une société » 的意思是？","options":["社会或公司","协会","会议"],"answer":"社会或公司","explain":"société 既可指社会，也可指公司，需要看上下文。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d20","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5024","level":"A2","skill":"listening","prompt":"新闻简讯的听力训练目标是？","options":["听懂 80% 的主旨与要点","听懂每个词","能逐句默写"],"answer":"听懂 80% 的主旨与要点","explain":"真实语料的听力目标是抓主旨与要点，不必逐词听懂。","source":"考试 · 听力策略"},{"id":"q-read-a2-5024","level":"A2","skill":"reading","prompt":"关系代词 où 可以指代？","options":["时间或地点","主语","直接宾语"],"answer":"时间或地点","explain":"où 指时间或地点状语；主语用 qui，直接宾语用 que。","source":"语法 · 关系代词"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 关系代词 qui / que / où 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#relatifs-a1a2 再核对一次。","src":"grammar-a1a2.html#prep-temps","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5047","level":"A2","skill":"grammar","prompt":"« C'est l'auteur ___ a écrit ce livre. »","options":["qui","que","dont"],"answer":"qui","explain":"从句缺主语，用 qui 作关系代词。","source":"语法 · 关系代词"},{"id":"q-gram-a2-5048","level":"A2","skill":"grammar","prompt":"「我两天前见过他」应说？","options":["Je l'ai vu il y a deux jours.","Je l'ai vu dans deux jours.","Je l'ai vu depuis deux jours."],"answer":"Je l'ai vu il y a deux jours.","explain":"il y a 加时间段表示「……以前」；dans 表将来某时，depuis 表以来。","source":"语法 · 时间介词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":26,"level":"A2","theme":"阶段测：DELF A2 模拟与复盘（词汇 1200）","days":[{"day":1,"theme":"词汇 · 人与身份","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：人与身份","body":"人与身份（L'être humain et l'identité）是这一周要反复见面的主题域。打开 vocab.html#t1，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un examen\">un examen</span>（考试）、<span class=\"fr\" data-fr=\"un progrès\">un progrès</span>（进步）、<span class=\"fr\" data-fr=\"une faute\">une faute</span>（错误）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t1","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5049","level":"A2","skill":"vocab","prompt":"« corriger » 的意思是？","options":["改正","抄写","评分"],"answer":"改正","explain":"corriger 是改正；copier 是抄写；noter 是评分。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"vocab","title":"搭配与辨析：corriger / un objectif","body":"<span class=\"fr\" data-fr=\"corriger\">corriger</span>（改正）与 <span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t1","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5050","level":"A2","skill":"vocab","prompt":"« une méthode » 的意思是？","options":["方法","记忆","动机"],"answer":"方法","explain":"méthode 是方法；mémoire 是记忆；motivation 是动机。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"listen","title":"听音辨词：人与身份","body":"打开 对话页的 d19 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"une méthode\">une méthode</span>（方法）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d19","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Nous sommes partis à la mer et il faisait très beau.\">Nous sommes partis à la mer et il faisait très beau.</span>（我们出发去了海边，天气很好。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：人与身份 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un examen\">un examen</span> <span class=\"fr\" data-fr=\"un progrès\">un progrès</span> <span class=\"fr\" data-fr=\"une faute\">une faute</span> <span class=\"fr\" data-fr=\"corriger\">corriger</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"une méthode\">une méthode</span>。说不出来的词立刻回到 vocab.html#t1 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t1","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:人与身份"}]}]},{"day":2,"theme":"语法 · 复合过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：复合过去时","body":"【复合过去时】这一周只做检测与补漏：完整做一套 A2 模拟（听力、阅读、写作 120 词、口语 5 分钟），全部限时；过去时体系专项 30 题检查复合过去时、未完成过去时与愈过去时的选择，目标是正确率不低于 85%。 例句：<span class=\"fr\" data-fr=\"Nous sommes partis à la mer et il faisait très beau.\">Nous sommes partis à la mer et il faisait très beau.</span>（我们出发去了海边，天气很好。）；<span class=\"fr\" data-fr=\"Elle avait déjà fini quand je suis arrivé.\">Elle avait déjà fini quand je suis arrivé.</span>（我到的时候她已经做完了。）。对照 grammar-a1a2.html#passe-compose 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#passe-compose","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5049","level":"A2","skill":"grammar","prompt":"「我到的时候她已经做完了」应说？","options":["Elle avait déjà fini quand je suis arrivé.","Elle a déjà fini quand je suis arrivé.","Elle finissait quand je suis arrivé."],"answer":"Elle avait déjà fini quand je suis arrivé.","explain":"更早发生的事用愈过去时，后发生的事件用复合过去时。","source":"语法 · 过去时体系"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#passe-compose 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Nous sommes partis à la mer et il faisait très beau.\">Nous sommes partis à la mer et il faisait très beau.</span>（我们出发去了海边，天气很好。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#passe-compose","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5050","level":"A2","skill":"grammar","prompt":"描写背景应该用？","options":["未完成过去时","复合过去时","愈过去时"],"answer":"未完成过去时","explain":"背景、状态与习惯用未完成过去时；事件用复合过去时；更早的事用愈过去时。","source":"语法 · 过去时体系"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"read","title":"在短文里找复合过去时","body":"在 grammar-a1a2.html#passe-compose 的例句和章末小测里挑 5 句，圈出所有属于「复合过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#passe-compose","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Nous sommes partis à la mer et il faisait très beau.\">Nous sommes partis à la mer et il faisait très beau.</span>（我们出发去了海边，天气很好。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，复合过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：未完成过去时","body":"今天再回 grammar-a1a2.html#imparfait 看一遍 未完成过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#imparfait","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d19 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d19 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d19","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5025","level":"A2","skill":"listening","prompt":"A2 听力中「先读题」的作用是？","options":["带着问题抓关键信息","降低语速","避免听错单词"],"answer":"带着问题抓关键信息","explain":"先读题干能在听力中定位答案句，减少无关信息干扰。","source":"考试 · 听力策略"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：完整做一套 A2 听力（约 20 分钟），限时，做完再对答案。","src":"dialogue.html#d19","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un examen\">un examen</span>（考试）、<span class=\"fr\" data-fr=\"un progrès\">un progrès</span>（进步）、<span class=\"fr\" data-fr=\"une faute\">une faute</span>（错误）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t1","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「复合过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d19","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · DELF A2 模拟与复盘（词汇 1200）","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：录 3 分钟自述，与第 13 周录音对比，记录进步点。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5013","level":"A2","skill":"speaking","prompt":"3 分钟自述的结构建议是？","options":["过去、现在、计划各一段","只讲过去","只讲计划"],"answer":"过去、现在、计划各一段","explain":"时间三分法能自然覆盖多种时态，也便于控制时长。","source":"口语 · 自述结构"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d19 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、复合过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d19","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"corriger\">corriger</span>（改正）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）、<span class=\"fr\" data-fr=\"une méthode\">une méthode</span>（方法）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t1 再看一遍例句。","src":"vocab.html#t1","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · DELF A2 模拟与复盘（词汇 1200）","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：做一套 A2 阅读（35 分钟），统计错题类型。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5025","level":"A2","skill":"reading","prompt":"A2 阅读错题里，「同义替换」问题指？","options":["题干用不同表达对应原文某句","单词不认识","时态判断错"],"answer":"题干用不同表达对应原文某句","explain":"同义替换题需要识别题干与原文的等价表达，是阅读的主要失分点。","source":"考试 · 阅读策略"},{"ref":"bank:reading:A2:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un examen\">un examen</span>（考试）、<span class=\"fr\" data-fr=\"un progrès\">un progrès</span>（进步）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t1","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#passe-compose，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#passe-compose","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「复合过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · DELF A2 模拟与复盘（词汇 1200）","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：限时写 150 词记叙，写完按五项自评标准打分。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5013","level":"A2","skill":"writing","prompt":"150 词记叙最基本的要求是？","options":["时间顺序清晰、时态一致","每句都用虚拟式","尽量写得长"],"answer":"时间顺序清晰、时态一致","explain":"记叙文先保证时间线与时态一致，再追求词汇丰富度。","source":"写作 · 记叙文"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#passe-compose，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#passe-compose","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「复合过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un examen\">un examen</span>（考试）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · DELF A2 模拟与复盘（词汇 1200）","type":"review","steps":[{"type":"review","title":"本周回顾：阶段测：DELF A2 模拟与复盘（词汇 1200）","body":"这一周围绕「阶段测：DELF A2 模拟与复盘（词汇 1200）」展开：语法主线是 复合过去时，词汇主线是 人与身份。先用 3 句话口头复述本周学了什么，再打开日历页第 26 周清单逐条核对里程碑。","src":"calendar.html#wk-26","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"语法复盘：复合过去时","body":"从 grammar-a1a2.html#passe-compose 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#passe-compose","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"review","title":"词汇自测：人与身份","body":"遮住中文看 vocab.html#t1 的 6 个核心词：<span class=\"fr\" data-fr=\"un examen\">un examen</span> <span class=\"fr\" data-fr=\"un progrès\">un progrès</span> <span class=\"fr\" data-fr=\"une faute\">une faute</span> <span class=\"fr\" data-fr=\"corriger\">corriger</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"une méthode\">une méthode</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t1","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5051","level":"A2","skill":"vocab","prompt":"« une faute » 的意思是？","options":["错误","缺点","罚金"],"answer":"错误","explain":"faute 指错误；défaut 是缺点；amende 是罚金。","source":"词汇 · 学习"},{"id":"q-vocab-a2-5052","level":"A2","skill":"vocab","prompt":"« un progrès » 的意思是？","options":["进步","程序","问题"],"answer":"进步","explain":"progrès 是进步；programme 是程序；problème 是问题。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d19","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5026","level":"A2","skill":"listening","prompt":"听力跟不上时，最有效的做法是？","options":["用已听到的关键词推断","停下来查词","放弃这一题"],"answer":"用已听到的关键词推断","explain":"考试中不能回放，用已知信息推断是必要的应试策略。","source":"考试 · 听力策略"},{"id":"q-read-a2-5026","level":"A2","skill":"reading","prompt":"过去时专项 30 题的正确率目标是？","options":["不低于 85%","不低于 50%","必须 100%"],"answer":"不低于 85%","explain":"课程表给出的目标是过去时体系专项正确率不低于 85%。","source":"语法 · 阶段目标"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 复合过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#passe-compose 再核对一次。","src":"grammar-a1a2.html#imparfait","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5051","level":"A2","skill":"grammar","prompt":"« Quand j'étais enfant, je ___ au parc. »（jouer）","options":["jouais","ai joué","avais joué"],"answer":"jouais","explain":"表示过去的习惯用未完成过去时 jouais。","source":"语法 · 未完成过去时"},{"id":"q-gram-a2-5052","level":"A2","skill":"grammar","prompt":"« Hier, elle ___ au cinéma. »（aller）","options":["est allée","allait","était allée"],"answer":"est allée","explain":"一次完成、时间明确的动作用复合过去时；aller 用 être 并配合成 allée。","source":"语法 · 复合过去时"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":27,"level":"B1","theme":"B1 起点：抽象话题词汇与关系从句","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"une personne\">une personne</span>（人）、<span class=\"fr\" data-fr=\"un quartier\">un quartier</span>（街区）、<span class=\"fr\" data-fr=\"influencer\">influencer</span>（影响）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5001","level":"B1","skill":"vocab","prompt":"« un modèle » 的意思是？","options":["榜样","模型","方式"],"answer":"榜样","explain":"modèle 可指榜样，也可指模型；manière 是方式。","source":"词汇 · 人与身份"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：un modèle / la solidarité","body":"把 <span class=\"fr\" data-fr=\"un modèle\">un modèle</span>（榜样）和 <span class=\"fr\" data-fr=\"la solidarité\">la solidarité</span>（团结）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5002","level":"B1","skill":"vocab","prompt":"« la solidarité » 的意思是？","options":["团结","孤独","稳定"],"answer":"团结","explain":"solidarité 是团结、互助；solitude 是孤独；stabilité 是稳定。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d30 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un habitant\">un habitant</span>（居民）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"C'est une personne qui m'a beaucoup aidé.\">C'est une personne qui m'a beaucoup aidé.</span>（这是一个帮了我很多的人。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une personne\">une personne</span> <span class=\"fr\" data-fr=\"un quartier\">un quartier</span> <span class=\"fr\" data-fr=\"influencer\">influencer</span> <span class=\"fr\" data-fr=\"un modèle\">un modèle</span> <span class=\"fr\" data-fr=\"la solidarité\">la solidarité</span> <span class=\"fr\" data-fr=\"un habitant\">un habitant</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · 关系代词进阶","type":"grammar","steps":[{"type":"grammar","title":"语法点：关系代词进阶","body":"【关系代词进阶】关系从句用关系代词把两个短句合并：qui 代替从句主语，que 代替直接宾语，où 代替时间或地点状语。B1 阶段要能连续使用关系从句，而不是把短句硬拼；先行词是人时同样用 qui / que，不必换成别的形式。 例句：<span class=\"fr\" data-fr=\"C'est une personne qui m'a beaucoup aidé.\">C'est une personne qui m'a beaucoup aidé.</span>（这是一个帮了我很多的人。）；<span class=\"fr\" data-fr=\"Le quartier où j'habite est très vivant.\">Le quartier où j'habite est très vivant.</span>（我住的街区很有活力。）。对照 grammar-b1b2.html#relatifs-b1 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#relatifs-b1","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5001","level":"B1","skill":"grammar","prompt":"« J'ai un ami ___ habite à Lyon. »","options":["qui","que","dont"],"answer":"qui","explain":"从句缺主语，用 qui。","source":"语法 · 关系代词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 关系代词进阶 的规则和两个例句，再打开 grammar-b1b2.html#relatifs-b1 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#relatifs-b1","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5002","level":"B1","skill":"grammar","prompt":"« Le film ___ nous avons vu était long. »","options":["que","qui","où"],"answer":"que","explain":"从句里 nous avons vu 缺直接宾语，用 que。","source":"语法 · 关系代词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"read","title":"在短文里找关系代词进阶","body":"在 grammar-b1b2.html#relatifs-b1 的例句和章末小测里挑 5 句，圈出所有属于「关系代词进阶」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#relatifs-b1","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"C'est une personne qui m'a beaucoup aidé.\">C'est une personne qui m'a beaucoup aidé.</span>（这是一个帮了我很多的人。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，关系代词进阶 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：qui / que / où 基础","body":"今天再回 grammar-a1a2.html#relatifs-a1a2 看一遍 qui / que / où 基础，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:关系代词"}]}]},{"day":3,"theme":"精听 · 对话页的 d30 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d30 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5001","level":"B1","skill":"listening","prompt":"访谈中 « la personne qui m'a aidé » 的 qui 在从句里作？","options":["主语","直接宾语","状语"],"answer":"主语","explain":"qui 在从句里作主语，后面直接跟动词。","source":"语法 · 关系代词"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一档人物访谈，记录 10 个关系从句。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une personne\">une personne</span>（人）、<span class=\"fr\" data-fr=\"un quartier\">un quartier</span>（街区）、<span class=\"fr\" data-fr=\"influencer\">influencer</span>（影响）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「关系代词进阶 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 抽象话题词汇与关系从句","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：描述一个影响过我的人 3 分钟，至少用 5 个关系从句。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5001","level":"B1","skill":"speaking","prompt":"描述影响我的人时，最自然的衔接方式是？","options":["用关系从句补充细节","把短句一条条并列","只描述外貌"],"answer":"用关系从句补充细节","explain":"关系从句让描述连贯，避免机械罗列短句。","source":"语法 · 关系从句"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、关系代词进阶 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un modèle\">un modèle</span>（榜样）、<span class=\"fr\" data-fr=\"la solidarité\">la solidarité</span>（团结）、<span class=\"fr\" data-fr=\"un habitant\">un habitant</span>（居民）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 抽象话题词汇与关系从句","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 600 词人物报道，画出所有关系代词。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5001","level":"B1","skill":"reading","prompt":"« le jour où je suis arrivé » 中 où 指代？","options":["时间","地点","人"],"answer":"时间","explain":"où 可以指时间，相当于「在……那天」。","source":"语法 · 关系代词"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「关系代词进阶」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une personne\">une personne</span>（人）、<span class=\"fr\" data-fr=\"un quartier\">un quartier</span>（街区）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#relatifs-b1，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#relatifs-b1","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「关系代词进阶」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 抽象话题词汇与关系从句","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 180 词人物描写，含 6 个关系从句。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5001","level":"B1","skill":"writing","prompt":"把「Voici un collègue. Il parle cinq langues.」合并是？","options":["Voici un collègue qui parle cinq langues.","Voici un collègue que parle cinq langues.","Voici un collègue dont parle cinq langues."],"answer":"Voici un collègue qui parle cinq langues.","explain":"两个短句合并时，后句主语用 qui 代替。","source":"语法 · 关系从句"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#relatifs-b1，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#relatifs-b1","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「关系代词进阶」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une personne\">une personne</span>（人）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 抽象话题词汇与关系从句","type":"review","steps":[{"type":"review","title":"本周回顾：B1 起点：抽象话题词汇与关系从句","body":"这一周围绕「B1 起点：抽象话题词汇与关系从句」展开：语法主线是 关系代词进阶，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 27 周清单逐条核对里程碑。","src":"calendar.html#wk-27","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：关系代词进阶","body":"从 grammar-b1b2.html#relatifs-b1 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#relatifs-b1","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:关系代词"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"une personne\">une personne</span> <span class=\"fr\" data-fr=\"un quartier\">un quartier</span> <span class=\"fr\" data-fr=\"influencer\">influencer</span> <span class=\"fr\" data-fr=\"un modèle\">un modèle</span> <span class=\"fr\" data-fr=\"la solidarité\">la solidarité</span> <span class=\"fr\" data-fr=\"un habitant\">un habitant</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5003","level":"B1","skill":"vocab","prompt":"« un habitant » 的意思是？","options":["居民","住所","习惯"],"answer":"居民","explain":"habitant 是居民；habitation 是住所；habitude 是习惯。","source":"词汇 · 社会"},{"id":"q-vocab-b1-5004","level":"B1","skill":"vocab","prompt":"« influencer » 的意思是？","options":["影响","涌入","通知"],"answer":"影响","explain":"influencer 是影响；affluer 是涌入；informer 是通知。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5002","level":"B1","skill":"listening","prompt":"听到 /la fam ki vjɛ̃ ditali/ 里的 /ki/ 对应哪个关系代词？","options":["qui","que","où"],"answer":"qui","explain":"/ki/ 后接动词，说明它在从句里作主语，是 qui。","source":"语法 · 关系代词"},{"id":"q-read-b1-5002","level":"B1","skill":"reading","prompt":"« L'homme que j'ai rencontré… » 中 que 在从句里作？","options":["直接宾语","主语","状语"],"answer":"直接宾语","explain":"que 后面接主语加动词，说明它在从句里作直接宾语。","source":"语法 · 关系代词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 关系代词进阶 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#relatifs-b1 再核对一次。","src":"grammar-a1a2.html#relatifs-a1a2","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5003","level":"B1","skill":"grammar","prompt":"« C'est le projet ___ je suis fier. »","options":["dont","que","qui"],"answer":"dont","explain":"être fier de 需要 de，用关系代词 dont。","source":"语法 · 关系代词"},{"id":"q-gram-b1-5004","level":"B1","skill":"grammar","prompt":"« La ville ___ il vient est petite. »","options":["d'où","où","que"],"answer":"d'où","explain":"venir de 需要 de，地点用 d'où 表示「从那里」。","source":"语法 · 关系代词"},{"ref":"bank:grammar:A2:关系代词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]}];
